import{_ as t,o,c as n,ag as a}from"./chunks/framework.D9ghT4bC.js";const u=JSON.parse('{"title":"Coding standards (UncivCN branch)","description":"","frontmatter":{},"headers":[],"relativePath":"UncivCN/Coding-standards.md","filePath":"UncivCN/Coding-standards.md"}'),r={name:"UncivCN/Coding-standards.md"};function s(d,e,i,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="coding-standards-uncivcn-branch" tabindex="-1">Coding standards (UncivCN branch) <a class="header-anchor" href="#coding-standards-uncivcn-branch" aria-label="Permalink to &quot;Coding standards (UncivCN branch)&quot;">​</a></h1><blockquote><p><strong>This is the engineering standards summary of the UncivCN branch — every item comes from an actual pitfall.</strong><strong>Read this document in full before touching docs, doc generators, unique definitions or translation-related code.</strong></p></blockquote><h2 id="_1-doc-site-maintenance-vitepress-vs-upstream-mkdocs" tabindex="-1">1. Doc site maintenance (VitePress vs upstream mkdocs) <a class="header-anchor" href="#_1-doc-site-maintenance-vitepress-vs-upstream-mkdocs" aria-label="Permalink to &quot;1. Doc site maintenance (VitePress vs upstream mkdocs)&quot;">​</a></h2><p>The UncivCN doc site (<code>docs-vitepress/</code>) uses VitePress (mkdocs was dropped: no Chinese search support); upstream still uses mkdocs. The two syntaxes are <strong>not compatible</strong> — these are the recorded pitfalls:</p><table tabindex="0"><thead><tr><th>Item</th><th>Upstream mkdocs</th><th>UncivCN VitePress</th></tr></thead><tbody><tr><td>Containers (admonitions)</td><td><code>!!! note</code> + content <strong>indented 4 spaces</strong></td><td><code>::: note</code> + content <strong>must not be indented</strong></td></tr><tr><td>Block types</td><td>all admonition types</td><td>built-in tip/info/warning/danger/details; <code>note</code> needs a custom registration</td></tr><tr><td>Abbreviation tooltips</td><td><code>*[param]: text</code> auto-renders <code>&lt;abbr&gt;</code></td><td>not supported — use a parameter table instead</td></tr><tr><td>Doc generator output</td><td>mkdocs format (indented containers)</td><td>VitePress format (non-indented containers)</td></tr></tbody></table><h3 id="writing-rules-all-from-real-pitfalls" tabindex="-1">Writing rules (all from real pitfalls) <a class="header-anchor" href="#writing-rules-all-from-real-pitfalls" aria-label="Permalink to &quot;Writing rules (all from real pitfalls)&quot;">​</a></h3><ol><li><strong>Never indent container content</strong>: 4 spaces / tabs inside a VitePress container are parsed as a code block (<code>&lt;pre&gt;</code>), which does not wrap and pushes long paragraphs off-screen. Applies to generator output and hand-written docs alike.</li><li><strong>Never translate JSON literals</strong>: unique texts, parameter names, Countables texts/examples must stay in English — the game matches them verbatim against <code>UniqueType.uniqueTypeMap</code>; a translated literal simply won&#39;t work, and modders copying from the docs would be misled.</li><li><strong>Number repeated parameters</strong>: in unique headings, repeated parameters are shown numbered (<code>[amount] [amount]</code> → <code>[amount]-[amount2]</code>, matching the translation template&#39;s <code>getTranslatable()</code>), so readers can tell them apart; example lines still use the raw text (directly copyable into mod JSON).</li><li><strong>Auto-generated docs are edited only through generator source</strong>: change the generator, then run <code>./gradlew desktop:generateDocs</code>; never hand-edit its output.</li><li><strong>Multi-line table cells</strong>: docDescriptions containing newlines break markdown tables; the generator replaces them with <code>&lt;br&gt;</code> — do the same when maintaining tables by hand.</li></ol><h2 id="_2-auto-generated-documents" tabindex="-1">2. Auto-generated documents <a class="header-anchor" href="#_2-auto-generated-documents" aria-label="Permalink to &quot;2. Auto-generated documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Generator</th><th>Maintenance</th></tr></thead><tbody><tr><td><code>docs/Modders/uniques.md</code></td><td><code>UniqueDocsWriter.write()</code></td><td><strong>fully generated</strong> — change the generator source</td></tr><tr><td><code>docs/zh/Modders/uniques.md</code></td><td><code>UniqueDocsWriter.writeChinese()</code></td><td><strong>fully generated</strong> — change the generator source</td></tr><tr><td><code>docs/Modders/Unique-parameters.md</code></td><td><code>UniqueDocsWriter.writeCountables()</code></td><td>marker region auto, rest hand-maintained</td></tr><tr><td><code>docs/zh/Modders/Unique-parameters.md</code></td><td><code>UniqueDocsWriter.writeCountables()</code></td><td>marker region auto (Chinese translations live in the generator), rest hand-maintained</td></tr><tr><td><code>docs/Modders/Mod-file-structure/6-MergeActions.md</code></td><td><code>MergeActionDocsWriter</code></td><td><strong>fully generated</strong></td></tr><tr><td><code>docs/Modders/Creating-a-UI-skin.md</code></td><td><code>UiElementDocsWriter</code></td><td>marker region auto, rest hand-maintained</td></tr><tr><td><code>docs/zh/Modders/Creating-a-UI-skin.md</code></td><td><code>UiElementDocsWriter</code></td><td>marker region auto, rest hand-maintained</td></tr><tr><td>All other <code>docs/</code>, <code>docs/zh/</code> pages</td><td>—</td><td>hand-maintained</td></tr></tbody></table><p><strong>Rule</strong>: generated docs are maintained exclusively by &quot;change the generator source + run <code>./gradlew desktop:generateDocs</code>&quot;; <strong>never hand-edit the output</strong>. The Chinese translations embedded in generators (<code>docsSentence</code> / <code>countablesTranslate</code>) are maintained with the source.</p><p>Local preview: double-click <code>docs-vitepress/build.bat</code> (build / open existing / rebuild+restart; the server auto-exits after 5 idle minutes).</p><h2 id="_3-unique-translation-conventions" tabindex="-1">3. Unique &amp; translation conventions <a class="header-anchor" href="#_3-unique-translation-conventions" aria-label="Permalink to &quot;3. Unique &amp; translation conventions&quot;">​</a></h2><ol><li><strong>Define <code>docDescriptionZh</code> alongside <code>docDescription</code></strong>: whenever you add or change a <code>docDescription</code> on a <code>UniqueType</code> / <code>UniqueParameterType</code>, <strong>also write <code>docDescriptionZh</code></strong> (the Chinese explanation) in the same place — the doc generator reads it automatically and falls back to English when missing. Never maintain big translation maps in the generator.</li><li><strong>Never translate JSON literals</strong> (see rule 2): unique texts, parameter names, Countables texts/examples stay in English; only explanatory prose is translated.</li><li><strong>Translation channels</strong>: <ul><li>Strings shown in-game → translation templates (<code>template.properties</code> / <code>Simplified_Chinese.properties</code>)</li><li>Doc-only strings (<code>docDescription</code>, UniqueTarget docs, Countables docs) → source fields (<code>docDescriptionZh</code>) or generator-embedded translations (<code>docsSentence</code> / <code>countablesTranslate</code>)</li></ul></li><li><strong>Key consistency</strong>: translation keys use <code>getTranslatable()</code> (numbered repeated placeholders); doc headings show the numbered form, but examples always use the raw text.</li></ol><h2 id="_4-branch-conventions" tabindex="-1">4. Branch conventions <a class="header-anchor" href="#_4-branch-conventions" aria-label="Permalink to &quot;4. Branch conventions&quot;">​</a></h2><ul><li><strong>Version</strong> = upstream version + CN sub-version (e.g. upstream 4.21.5 → UncivCN 4.21.5.1; the same upstream version may get <code>.1</code>/<code>.2</code>/<code>.3</code>…, e.g. 4.20.8.1 → 4.20.8.4; the sub-version restarts at <code>.1</code> after merging a new upstream), defined in <code>buildSrc/src/main/kotlin/BuildConfig.kt</code></li><li><strong>Additive changes</strong>: new features must not change upstream behavior; with options off the game behaves like upstream</li><li><strong>Doc mirroring</strong>: <code>docs/zh/</code> mirrors the English section one-to-one (same path = the translation); Chinese-only content lives only in <code>docs/zh/UncivCN/</code> and <code>docs/zh/Community/</code></li><li><strong>Chinese as first-class</strong>: new UI strings must go into the translation templates; new unique explanations must ship with Chinese</li></ul><h2 id="_5-changelog-release-process" tabindex="-1">5. Changelog &amp; release process <a class="header-anchor" href="#_5-changelog-release-process" aria-label="Permalink to &quot;5. Changelog &amp; release process&quot;">​</a></h2><ul><li><strong>Log every change, not just releases</strong>: any non-release change (feature / bugfix / CI / docs site) merged into the branch must add one line to the <strong>Unreleased</strong> section at the top of both <code>docs/UncivCN/Changelog.md</code> and <code>docs/zh/UncivCN/Changelog.md</code>, in the same commit as the change itself. Entries only accumulate there until the next release.</li><li><strong>Consolidate on release</strong>: when releasing, move the whole Unreleased section into the new version entry (<code>## vX.Y.Z.N (build NNNN)</code>), keeping the same wording, then empty the Unreleased section.</li><li><strong>Version bump</strong>: only edit <code>buildSrc/src/main/kotlin/BuildConfig.kt</code> (<code>appVersion</code> + <code>appCodeNumber</code> +1). The <code>syncGameVersion</code> Gradle task runs before every core build and automatically mirrors the values into the <code>AUTOMATICALLY GENERATED VERSION DATA</code> region of <code>UncivGame.kt</code> (the in-game version display) — never hand-edit that region.</li><li><strong>Release tag</strong>: the MSI installer version comes from the git tag (<code>github.ref_name</code>, 4-segment form like <code>4.21.5.3</code>); every release must push a tag matching the version to trigger the Deploy workflow.</li><li><strong>Upstream changelog pages</strong>: the English page <code>docs/Community/Upstream-changelog.md</code> embeds the full repo-root <code>changelog.md</code> at build time (the <code>upstream-changelog</code> container in <code>docs-vitepress/.vitepress/config.ts</code>), so it stays current automatically after every upstream merge — never maintain an English copy by hand. The Chinese page <code>docs/zh/Community/Upstream-changelog.md</code> is <strong>human-translated only, no embedded English</strong>: it covers recent versions (may lag) and links to the EN page for the full history; backfill translations gradually, newest versions first.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./Differences.html">Differences vs upstream</a></li><li><a href="./Changelog.html">Changelog</a></li></ul>',19)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
